<?php get_header();while(have_posts()):the_post(); ?><main class="container section"><div class="single-layout"><article><div class="single-hero"><h1><?php the_title(); ?></h1><?php if(has_post_thumbnail())the_post_thumbnail('full'); ?></div><div class="article-content"><?php the_content(); ?></div></article><aside class="store-info"><h2>店家資訊</h2><?php $fields=array('bsktv_address'=>'地址','bsktv_hours'=>'營業時間','bsktv_phone'=>'電話','bsktv_line'=>'LINE／聯絡方式','bsktv_price'=>'消費區間','bsktv_model'=>'消費模式','bsktv_room'=>'包廂資訊');foreach($fields as $k=>$label){$v=bsktv_meta($k);if($v)echo '<div class="info-row"><span class="info-label">'.esc_html($label).'</span>'.esc_html($v).'</div>';}if($map=bsktv_meta('bsktv_map'))echo '<p><a class="btn" target="_blank" rel="noopener" href="'.esc_url($map).'">查看地圖</a></p>'; ?></aside></div></main><?php endwhile;get_footer(); ?>